#include "NeuralSensoryInterpolator.h"
#include <algorithm>
namespace dnxr { FullDiveNeuralFrame NeuralSensoryInterpolator::interpolate(const FullDiveNeuralFrame& prev, const FullDiveNeuralFrame& next, float alpha, bool emergency) const { if(emergency) return next; FullDiveNeuralFrame out=next; const float a=std::clamp(alpha,0.0f,1.0f); auto blend=[a](const auto& p, auto& n){ const auto count=std::min(p.channels.size(),n.channels.size()); for(size_t i=0;i<count;++i){ n.channels[i].intensity=p.channels[i].intensity*(1.0f-a)+n.channels[i].intensity*a; n.channels[i].phase=p.channels[i].phase*(1.0f-a)+n.channels[i].phase*a; } }; blend(prev.visual,out.visual); blend(prev.auditory,out.auditory); blend(prev.somatosensory,out.somatosensory); blend(prev.proprioception,out.proprioception); blend(prev.vestibular,out.vestibular); blend(prev.smellTaste.olfactory,out.smellTaste.olfactory); blend(prev.smellTaste.gustatory,out.smellTaste.gustatory); return out; } }
